package ledger

// Refactoring log (this exercise is a refactor; the tests are the ground truth):
//
//  1. Replaced the hand-rolled bubble sort (with its m1/m2 sign maps and
//     nested loops) with sort.Slice on a copy of the entries, comparing
//     date, then description, then change. The copy also removes the need
//     for the separate entriesCopy bookkeeping.
//  2. Removed the goroutine/channel fan-out used to format rows; rows are
//     formatted sequentially. The results are identical and the code is
//     much simpler.
//  3. Collapsed the repeated "if nl-NL / else if en-US" branches into a
//     table of localeSettings (header words, date layout, number
//     separators, sign decoration) plus a small currency symbol table.
//  4. Replaced the errors.New("") sentinel errors with descriptive errors,
//     and validated currency and locale up front instead of via the
//     recursive dummy-entry hack used for empty ledgers.
//  5. Made date validation explicit: fixed 10-char "Y-m-d" shape with '-'
//     separators, plus month/day range checks.
//  6. Centralised string padding in rune-aware padLeft/padRight helpers so
//     multi-byte characters (e.g. "€") are measured correctly, and moved
//     description truncation into its own helper.
//  7. Built the output with strings.Builder instead of repeated
//     concatenation.

import (
	"fmt"
	"sort"
	"strconv"
	"strings"
	"unicode/utf8"
)

// Entry is a single line of the ledger. Change is expressed in cents.
type Entry struct {
	Date        string // "Y-m-d"
	Description string
	Change      int // in cents
}

// localeSettings describes how a supported locale renders the ledger.
type localeSettings struct {
	headerDate   string
	headerDesc   string
	headerChange string

	symbolGap    string // gap between the currency symbol and the digits
	thousandsSep string
	decimalSep   string

	negPrefix string // wraps a negative amount
	negSuffix string
	posSuffix string // trails a positive amount

	dateLayout func(year, month, day string) string
}

var locales = map[string]localeSettings{
	"en-US": {
		headerDate:   "Date",
		headerDesc:   "Description",
		headerChange: "Change",
		thousandsSep: ",",
		decimalSep:   ".",
		negPrefix:    "(",
		negSuffix:    ")",
		posSuffix:    " ",
		dateLayout:   func(year, month, day string) string { return month + "/" + day + "/" + year },
	},
	"nl-NL": {
		headerDate:   "Datum",
		headerDesc:   "Omschrijving",
		headerChange: "Verandering",
		symbolGap:    " ",
		thousandsSep: ".",
		decimalSep:   ",",
		negSuffix:    "-",
		posSuffix:    " ",
		dateLayout:   func(year, month, day string) string { return day + "-" + month + "-" + year },
	},
}

var currencySymbols = map[string]string{
	"USD": "$",
	"EUR": "€",
}

// FormatLedger returns the entries rendered as a fixed-width ledger table
// for the given currency and locale. The input slice is not modified.
func FormatLedger(currency string, locale string, entries []Entry) (string, error) {
	symbol, ok := currencySymbols[currency]
	if !ok {
		return "", fmt.Errorf("unsupported currency %q", currency)
	}
	l, ok := locales[locale]
	if !ok {
		return "", fmt.Errorf("unsupported locale %q", locale)
	}

	// Sort a copy of the entries so the caller's slice is left untouched.
	sorted := make([]Entry, len(entries))
	copy(sorted, entries)
	sort.Slice(sorted, func(i, j int) bool {
		a, b := sorted[i], sorted[j]
		if a.Date != b.Date {
			return a.Date < b.Date
		}
		if a.Description != b.Description {
			return a.Description < b.Description
		}
		return a.Change < b.Change
	})

	var sb strings.Builder
	sb.WriteString(padRight(l.headerDate, 10))
	sb.WriteString(" | ")
	sb.WriteString(padRight(l.headerDesc, 25))
	sb.WriteString(" | ")
	sb.WriteString(l.headerChange)
	sb.WriteString("\n")

	for _, e := range sorted {
		date, err := formatEntryDate(e.Date, l)
		if err != nil {
			return "", err
		}
		sb.WriteString(date)
		sb.WriteString(" | ")
		sb.WriteString(formatDescription(e.Description))
		sb.WriteString(" | ")
		sb.WriteString(padLeft(l.formatAmount(e.Change, symbol), 13))
		sb.WriteString("\n")
	}
	return sb.String(), nil
}

// formatEntryDate validates an ISO "Y-m-d" date and renders it in the
// locale's layout.
func formatEntryDate(date string, l localeSettings) (string, error) {
	if len(date) != 10 || date[4] != '-' || date[7] != '-' {
		return "", fmt.Errorf("invalid date %q", date)
	}
	year, month, day := date[0:4], date[5:7], date[8:10]
	if m, _ := strconv.Atoi(month); m < 1 || m > 12 {
		return "", fmt.Errorf("invalid month in date %q", date)
	}
	if d, _ := strconv.Atoi(day); d < 1 || d > 31 {
		return "", fmt.Errorf("invalid day in date %q", date)
	}
	return l.dateLayout(year, month, day), nil
}

// formatAmount renders a change in cents with the locale's number format.
func (l localeSettings) formatAmount(cents int, symbol string) string {
	negative := cents < 0
	if negative {
		cents = -cents
	}
	dollars, rem := cents/100, cents%100
	amount := symbol + l.symbolGap +
		groupThousands(strconv.Itoa(dollars), l.thousandsSep) +
		l.decimalSep + fmt.Sprintf("%02d", rem)
	if negative {
		return l.negPrefix + amount + l.negSuffix
	}
	return amount + l.posSuffix
}

// formatDescription truncates overlong descriptions and pads to the
// description column width.
func formatDescription(desc string) string {
	if runes := []rune(desc); len(runes) > 25 {
		desc = string(runes[:22]) + "..."
	}
	return padRight(desc, 25)
}

// groupThousands inserts sep between every group of three digits, counting
// from the right.
func groupThousands(digits string, sep string) string {
	if len(digits) <= 3 {
		return digits
	}
	var sb strings.Builder
	for i, c := range digits {
		if i > 0 && (len(digits)-i)%3 == 0 {
			sb.WriteString(sep)
		}
		sb.WriteByte(byte(c))
	}
	return sb.String()
}

// padRight pads s with trailing spaces up to width runes.
func padRight(s string, width int) string {
	if n := utf8.RuneCountInString(s); n < width {
		s += strings.Repeat(" ", width-n)
	}
	return s
}

// padLeft pads s with leading spaces up to width runes.
func padLeft(s string, width int) string {
	if n := utf8.RuneCountInString(s); n < width {
		s = strings.Repeat(" ", width-n) + s
	}
	return s
}
